def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    opp = [o for m, o in history]
    mine = [m for m, o in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = mine.count('C')
    my_d = n - my_c

    # helper: opponent cooperation in last k
    k10 = min(10, n)
    rec_opp = opp[-k10:]
    rec_c = rec_opp.count('C')
    rec_d = k10 - rec_c

    # helper: consecutive DD run length
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if mine[i] == 'D' and opp[i] == 'D':
            dd_run += 1
        else:
            break

    # helper: consecutive exploitation (my C, opp D) run
    exploit_run = 0
    for i in range(n - 1, -1, -1):
        if mine[i] == 'C' and opp[i] == 'D':
            exploit_run += 1
        else:
            break

    # --- Hard detection of sustained defectors ---
    if n >= 6:
        last6 = opp[-6:]
        if last6.count('D') >= 5:
            # Nearly always defecting: punish, but probe rarely to allow restart
            if n % 13 == 0:
                return 'C'
            return 'D'

    # --- Detect always-cooperate opponent ---
    if opp_d == 0:
        # Never defected. Exploit moderately late, otherwise cooperate.
        if n >= 95:
            return 'D'
        if n % 11 == 0 and n >= 20:
            return 'D'
        return 'C'

    # --- Detect very cooperative opponent ---
    if n >= 12 and rec_d <= 1:
        # Mostly cooperating: maintain CC and occasionally exploit.
        if n >= 95:
            return 'D'
        if n % 9 == 0 and n >= 25:
            return 'D'
        return 'C'

    # --- Final rounds: try to grab last-round gain if opponent likely to C ---
    if n >= 96:
        if rec_d == 0:
            return 'D'
        if rec_c > rec_d:
            return 'D'
        return 'D'

    if n >= 90:
        if rec_d >= 3:
            return 'D'
        if rec_d == 0:
            # likely still cooperating
            if n % 2 == 1:
                return 'D'
            return 'C'
        return 'C' if rec_c >= rec_d else 'D'

    # --- Defection spiral recovery ---
    if dd_run >= 3:
        # Try to break mutual defection
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # --- Exploitation: opponent keeps taking while I cooperate ---
    if exploit_run >= 2:
        return 'D'

    last_m, last_o = history[-1]

    # --- Opponent defected just now ---
    if last_o == 'D':
        if last_m == 'D':
            # We are in punishment: keep punishing unless mild
            if rec_d >= 6:
                return 'D'
            if rec_c >= 4:
                return 'D'
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            # I cooperated, got exploited: retaliate
            if opp_d * 2 < n and rec_d <= 2:
                # Mostly cooperating opponent: forgive once
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'D'

    # --- Opponent cooperated just now ---
    # If I defected last round, return to cooperation (rebuild)
    if last_m == 'D':
        return 'C'

    # Both cooperated: continue
    # Occasionally probe against very cooperative opponents already handled above.
    # Against mixed opponents, small chance to defect late to test.
    if n >= 30 and opp_d * 3 < n and n % 17 == 0:
        return 'D'

    return 'C'
